      primaryMuscle: $ExercisesTable.$converterprimaryMuscle.fromJson(
        serializer.fromJson<String>(json['primaryMuscle']),
      ),
      secondaryMuscles: serializer.fromJson<String>(json['secondaryMuscles']),
